   241	// runStop is the main logic for the stop command.
   242	func runStop(ctx context.Context, cmd *cobra.Command, sessionID string, all, force bool) error {
   243		// --session path: stop a specific session by explicit ID (no worktree scoping).
   244		if sessionID != "" {
   245			return runStopSession(ctx, cmd, sessionID, force)
   246		}
   247	
   248		// List all session states
   249		states, err := strategy.ListSessionStates(ctx)
   250		if err != nil {
   251			return fmt.Errorf("failed to list sessions: %w", err)
   252		}
   253	
   254		activeSessions := filterActiveSessions(states)
   255	
   256		// --all path: stop all active sessions across all worktrees.
   257		if all {
   258			return runStopAll(ctx, cmd, activeSessions, force)
   259		}
   260	
   261		// No-flags path: show all active sessions across all worktrees.
   262		// This aligns with `entire status` which displays sessions globally.
   263		// Users see worktree labels in the multi-select to make informed choices.
   264		if len(activeSessions) == 0 {
   265			fmt.Fprintln(cmd.OutOrStdout(), "No active sessions.")
   266			return nil
   267		}
   268	
   269		// One active session: confirm + stop.
   270		if len(activeSessions) == 1 {
   271			return runStopSession(ctx, cmd, activeSessions[0].SessionID, force)
   272		}
   273	
   274		// Multiple active sessions: show TUI multi-select.
   275		return runStopMultiSelect(ctx, cmd, activeSessions, force)
   276	}
