   278	// filterActiveSessions returns sessions that have not been explicitly ended.
   279	// A session is considered ended if Phase == PhaseEnded OR EndedAt is set.
   280	// This matches the logic in status.go's writeActiveSessions for consistency:
   281	// any session visible in `entire status` should also be visible in `sessions stop`.
   282	func filterActiveSessions(states []*strategy.SessionState) []*strategy.SessionState {
   283		var active []*strategy.SessionState
   284		for _, s := range states {
   285			if s == nil {
   286				continue
   287			}
   288			if s.Phase != session.PhaseEnded && s.EndedAt == nil {
   289				active = append(active, s)
   290			}
   291		}
   292		return active
   293	}
